import{_ as d,C as s,o as c,c as l,a2 as i,E as o,j as t,a as n}from"./chunks/framework.TaNiW7i8.js";const y=JSON.parse('{"title":"Git synchronization","description":"","frontmatter":{"title":"Git synchronization"},"headers":[],"relativePath":"en/reference/mcp/git.md","filePath":"en/reference/mcp/git.md"}'),u={name:"en/reference/mcp/git.md"};function m(p,e,h,_,g,f){const r=s("AskExample"),a=s("McpResume");return c(),l("div",null,[e[0]||(e[0]=i('<h1 id="git-synchronization" tabindex="-1">Git synchronization <a class="header-anchor" href="#git-synchronization" aria-label="Permalink to &quot;Git synchronization&quot;">​</a></h1><p>These tools drive the <strong>system Git on the vault&#39;s repository</strong>: read its state, synchronize it with the remote, commit, resolve a real conflict. Initializing the repository or connecting it to a remote is done in the application, not here.</p><p><code>mem_git_status</code> writes nothing to the vault. <code>mem_git_sync</code>, <code>mem_git_commit</code> and <code>mem_git_resolve</code> act on the repository; <code>mem_git_commit</code> and <code>mem_git_resolve</code> should only be called with the user&#39;s agreement, as their descriptions say.</p><p>To ask for them by talking to your agent, see <a href="/Kessho/en/agent/synchroniser.html">Sync the memory</a>.</p><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2>',5)),o(r,{tool:"mem_git_status"}),o(r,{tool:"mem_git_sync"}),o(r,{tool:"mem_git_commit"}),e[1]||(e[1]=t("h2",{id:"the-tools",tabindex:"-1"},[n("The tools "),t("a",{class:"header-anchor",href:"#the-tools","aria-label":'Permalink to "The tools"'},"​")],-1)),e[2]||(e[2]=t("h2",{id:"mem-git-status",tabindex:"-1"},[t("code",null,"mem_git_status"),n(),t("a",{class:"header-anchor",href:"#mem-git-status","aria-label":'Permalink to "`mem_git_status`"'},"​")],-1)),o(a,{tool:"mem_git_status"}),e[3]||(e[3]=i('<p>Rend l&#39;état git du vault : branche, distant (sans identifiants), en avance / en retard sur la branche suivie, changements non commités comptés et listés, opération en cours, fichiers suivis portant des marqueurs de conflit, et l&#39;état du greffon Obsidian Git. Sans réseau par défaut ; <code>fetch: true</code> interroge d&#39;abord le distant. N&#39;écrit rien dans le vault. Git introuvable n&#39;est pas une erreur : l&#39;état le dit, avec la commande d&#39;installation.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>fetch</code></td><td>boolean</td><td>non / no</td><td>Vrai : <code>git fetch origin</code> d&#39;abord, pour que en avance / en retard soient à jour. Faux (défaut) : aucun réseau.</td></tr></tbody></table><h2 id="mem-git-sync" tabindex="-1"><code>mem_git_sync</code> <a class="header-anchor" href="#mem-git-sync" aria-label="Permalink to &quot;`mem_git_sync`&quot;">​</a></h2>',3)),o(a,{tool:"mem_git_sync"}),e[4]||(e[4]=t("p",null,[n("Synchronise le vault avec son distant : fetch, rebase des commits locaux si le distant a avancé, puis poussée. Jamais forcé, jamais d'autostash. Un conflit réel ANNULE le rebase (le dépôt revient à l'état d'avant, aucun marqueur n'est laissé) et rend les fichiers en cause — le résoudre est une tâche, voir la procédure mem-git. Refusé si des changements non commités empêchent le rebase. À appeler en début et en fin de session, et quand un compte rendu de synchronisation n'est pas "),t("code",null,"synchronise"),n(".")],-1)),e[5]||(e[5]=t("p",null,"Aucun paramètre. / No parameters.",-1)),e[6]||(e[6]=t("h2",{id:"mem-git-commit",tabindex:"-1"},[t("code",null,"mem_git_commit"),n(),t("a",{class:"header-anchor",href:"#mem-git-commit","aria-label":'Permalink to "`mem_git_commit`"'},"​")],-1)),o(a,{tool:"mem_git_commit"}),e[7]||(e[7]=i('<p>Commite les changements non commités du vault — tous, ou les chemins donnés — avec le message fourni, puis pousse (par défaut). Refusé si un fichier à commiter porte des marqueurs de conflit. À n&#39;appeler qu&#39;avec l&#39;accord explicite de l&#39;utilisateur : ces changements sont les siens.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>allow_markers</code></td><td>boolean</td><td>non / no</td><td>Vrai : un fichier qui CITE un marqueur de conflit (une note qui parle de git, un bloc de code) est accepté. Faux (défaut) : refusé.</td></tr><tr><td><code>message</code></td><td>string</td><td>oui / yes</td><td>Message de commit, non vide, 1 000 caractères au plus.</td></tr><tr><td><code>paths</code></td><td>array&lt;string&gt;</td><td>non / no</td><td>Chemins relatifs au vault à commiter. Absent : tous les changements.</td></tr><tr><td><code>push</code></td><td>boolean</td><td>non / no</td><td>Pousser après le commit (vrai par défaut).</td></tr></tbody></table><h2 id="mem-git-resolve" tabindex="-1"><code>mem_git_resolve</code> <a class="header-anchor" href="#mem-git-resolve" aria-label="Permalink to &quot;`mem_git_resolve`&quot;">​</a></h2>',3)),o(a,{tool:"mem_git_resolve"}),e[8]||(e[8]=i('<p>Résout un conflit git RÉEL entre ce poste et le distant, en deux temps. SANS <code>resolutions</code> : inspecte — fetch, prépare la fusion du distant, rend pour chaque fichier en conflit ses trois versions (<code>base</code>, <code>local</code>, <code>distant</code>) et une <code>empreinte</code>, puis annule : le dépôt ne change pas. AVEC <code>resolutions</code> et l&#39;<code>empreinte</code> rendue : refait la même fusion, écrit le texte résolu de chaque fichier (aucun marqueur de conflit accepté ; <code>content: null</code> explicite supprime le fichier ; un fichier <code>binaire</code> ne se résout que par <code>keep: local | distant</code>), régénère les index dérivés, commite la fusion et pousse. Tout échec annule la fusion : aucun marqueur n&#39;est jamais laissé. À n&#39;employer qu&#39;avec l&#39;accord de l&#39;utilisateur sur le texte fusionné. Voir la procédure mem-git.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>allow_markers</code></td><td>boolean</td><td>non / no</td><td>Vrai : un texte résolu qui CITE un marqueur de conflit (une note qui parle de git) est accepté. Faux (défaut) : refusé.</td></tr><tr><td><code>fingerprint</code></td><td>string</td><td>non / no</td><td>L&#39;<code>empreinte</code> rendue par l&#39;inspection. Obligatoire avec <code>resolutions</code> : si le dépôt ou le distant a bougé depuis, rien n&#39;est fait.</td></tr><tr><td><code>resolutions</code></td><td>array&lt;object&gt;</td><td>non / no</td><td>Absent : inspecter. Présent : le texte résolu de CHAQUE fichier en conflit rendu par l&#39;inspection (les index dérivés sont régénérés, ne pas les fournir).</td></tr><tr><td><code>resolutions[].content</code></td><td>string</td><td>null</td><td>non / no</td></tr><tr><td><code>resolutions[].keep</code></td><td>string</td><td>non / no</td><td>Au lieu de <code>content</code> : « local » ou « distant », garder ce côté tel quel, octet pour octet. Seul choix accepté pour un fichier <code>binaire</code>.</td></tr><tr><td><code>resolutions[].path</code></td><td>string</td><td>oui / yes</td><td>Chemin relatif au vault, tel que l&#39;inspection l&#39;a rendu.</td></tr></tbody></table>',2))])}const v=d(u,[["render",m]]);export{y as __pageData,v as default};
